package golang

import (
	"bytes"
	"fmt"
	"go/format"
	"strings"
	"testing"

	"github.com/masagroup/soft.gen/v2/internal/engine/goldentest"
)

// The first line of a file generated by v1 and by v2: the only difference
// that every file has, which the comparison ignores.
const (
	v1Header = "// Code generated by soft.generator.go. DO NOT EDIT."
	v2Header = "// Code generated by soft.gen go. DO NOT EDIT."
)

// TestV1 compares the v1 generator with the expected files of every case: the
// docker image named by SOFT_GEN_V1_IMAGE generates the case, its header line
// is the v2 one, its .go files are formatted with gofmt, and every file must
// equal its expected file, but the V1Differences of the case.
func TestV1(t *testing.T) {
	suite.TestV1(t, goldentest.V1{
		ImageEnv: "SOFT_GEN_V1_IMAGE",
		Image:    "masagroup/soft.generator.go:v1.13.1",
		File:     normalizeV1,
	})
}

// normalizeV1 gives a file of v1 the v2 header line and gofmt's layout.
func normalizeV1(file string, content []byte) ([]byte, error) {
	content = bytes.Replace(content, []byte(v1Header), []byte(v2Header), 1)
	if !strings.HasSuffix(file, ".go") {
		return content, nil
	}
	formatted, err := format.Source(content)
	if err != nil {
		return nil, fmt.Errorf("v1 output does not parse: %w", err)
	}
	return formatted, nil
}
